    private string LoadHtmlTemplate(string strRelativePath, string strFallbackTitle)
    {
        string[] arrPaths = new string[] {
            Application.StartupPath + "\\" + strRelativePath,
            Application.StartupPath + "\\..\\..\\" + strRelativePath,
            Application.StartupPath + "\\..\\..\\..\\" + strRelativePath
        };

        for (int i = 0; i < arrPaths.Length; i++)
        {
            try
            {
                string strFull = System.IO.Path.GetFullPath(arrPaths[i]);
                if (System.IO.File.Exists(strFull))
                    return System.IO.File.ReadAllText(strFull, Encoding.UTF8);
            }
            catch
            {
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.Append("<!DOCTYPE html><html><head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />");
        sb.Append("<title>").Append(strFallbackTitle).Append("</title>");
        sb.Append("<style type=\"text/css\">body{font-family:'Times New Roman',Times,serif;font-size:11pt;margin:12px;}</style>");
        sb.Append("</head><body>{CONTENT}</body></html>");
        return sb.ToString();
    }

    private void SaveAndOpenHtml(string strFileName, string strContent)
    {
        string strExportDir = Application.StartupPath + "\\Export";
        if (!System.IO.Directory.Exists(strExportDir))
            System.IO.Directory.CreateDirectory(strExportDir);

        string strFilePath = strExportDir + "\\" + strFileName;
        System.IO.File.WriteAllText(strFilePath, strContent, Encoding.UTF8);
        System.Diagnostics.Process.Start(strFilePath);
    }

    /// <summary>
    /// Xuất HTML - Bảng điểm học tập và tốt nghiệp (cấu trúc giống Leaning_BangDiemTotNghiep_QC04).
    /// Dữ liệu truyền y như btnPrint_Click.
    /// </summary>
    private void ExportBangDiemHocTapTotNghiep_HTML()
    {
        try
        {
            SIM_Student objStudentMarkSummary = new SIM_Student();
            SIM_Class_Subject objClassSubject = new SIM_Class_Subject();

            foreach (int i in gvData.GetSelectedRows())
            {
                DataRow drw = gvData.GetDataRow(i);
                DataTable dtbStudentMarkSummary = objStudentMarkSummary.SearchStudentMarkSummary(Convert.ToInt64(drw[SIM_Student.C_StudentID]));

                DataTable dtbDataQP = dtbStudentMarkSummary.Copy();
                dtbDataQP.DefaultView.RowFilter = "SpecialType=7";
                dtbDataQP = dtbDataQP.DefaultView.ToTable();

                DataTable dtbDataTC = dtbStudentMarkSummary.Copy();
                dtbDataTC.DefaultView.RowFilter = "SpecialType=6";
                dtbDataTC = dtbDataTC.DefaultView.ToTable();

                DataTable dtbData2 = dtbStudentMarkSummary.Copy();
                dtbData2.DefaultView.RowFilter = "SpecialType =1";
                dtbData2 = dtbData2.DefaultView.ToTable();

                DataTable dtbClassSubject = objClassSubject.SearchSubject_Graduation1(Convert.ToInt64(drw[SIM_Student.C_StudentID]));
                bool bolHasVH = dtbClassSubject.Rows.Count > 3;

                if (dtbData2 == null || dtbData2.Rows.Count == 0)
                {
                    ErrorManager.Error("Việc lấy thông tin sinh viên bị lỗi!");
                    continue;
                }

                if (dtbData2.Rows.Count % 2 != 0)
                {
                    DataRow dr = dtbData2.NewRow();
                    dr["GraduationLevel"] = dtbStudentMarkSummary.Rows[0]["GraduationLevel"];
                    dr["GraduationRankingAverage"] = dtbStudentMarkSummary.Rows[0]["GraduationRankingAverage"];
                    dr["SummaryLearningMark"] = dtbStudentMarkSummary.Rows[0]["SummaryLearningMark"];
                    dr["SummaryEthicLevel"] = dtbStudentMarkSummary.Rows[0]["SummaryEthicLevel"];
                    dtbData2.Rows.Add(dr);
                }

                DataRow drwInfo = dtbStudentMarkSummary.Rows[0];
                int intRegulationID = Convert.ToInt32(dtbStudentMarkSummary.Rows[0]["RegulationID"]);

                if (intRegulationID != 99)
                {
                    if (dtbClassSubject.Rows.Count == 0)
                    {
                        MessageManager.Warning("Không thể xuất mẫu này cho sinh viên chưa tốt nghiệp!");
                        continue;
                    }
                }

                string strSubjectNameTC = "";
                string strSubjectMarkTC = "";
                string strSubjectNameQP = "";
                string strSubjectMarkQP = "";

                if (dtbDataTC.Rows.Count > 0)
                {
                    strSubjectNameTC = GetDataRowText(dtbDataTC.Rows[0], "SubjectName");
                    decimal decTC = Convert.ToDecimal(dtbDataTC.Rows[0]["FinalSummary"]);
                    strSubjectMarkTC = String.Format("{0:0.0}", decTC);
                }

                if (dtbDataQP.Rows.Count > 0)
                {
                    strSubjectNameQP = GetDataRowText(dtbDataQP.Rows[0], "SubjectName");
                    decimal decQP = Convert.ToDecimal(dtbDataQP.Rows[0]["FinalSummary"]);
                    strSubjectMarkQP = String.Format("{0:0.0}", decQP);
                }

                StringBuilder sb = new StringBuilder();
                sb.Append("<div class='print-page'>");
                sb.Append(BuildHtmlHeaderBlock());
                sb.Append("<div class='title'>BẢNG ĐIỂM KẾT QUẢ HỌC TẬP TOÀN KHÓA</div>");
                sb.Append(BuildStudentInfoHtml_QC04(drwInfo));
                sb.Append(BuildSubjectTableHtml_QC04(dtbData2));

                if (intRegulationID != 99)
                    sb.Append(BuildGraduationExamHtml_QC04(dtbClassSubject, bolHasVH));

                sb.Append(BuildGraduationSummaryHtml_QC04(drwInfo));
                sb.Append(BuildExtraSubjectHtml_QC04(strSubjectNameTC, strSubjectMarkTC, strSubjectNameQP, strSubjectMarkQP));
                sb.Append(BuildSignatureHtml_QC04());
                sb.Append("</div>");

                string strTemplate = LoadHtmlTemplate("MauHTML\\BangDiem\\BangDiem_HocTapTotNghiep_QC04.htm", "Bảng điểm kết quả học tập toàn khóa");
                string strFileContent = strTemplate.Replace("{CONTENT}", sb.ToString());

                string strStudentCode = GetDataRowText(drwInfo, "StudentCode");
                if (strStudentCode == null || strStudentCode.Length < 1)
                    strStudentCode = Convert.ToString(drw[SIM_Student.C_StudentID]);
                strStudentCode = strStudentCode.Replace("\\", "_").Replace("/", "_").Replace(":", "_");

                SaveAndOpenHtml(strStudentCode + "_BangDiem_HocTapTotNghiep.htm", strFileContent);
            }
        }
        catch
        {
            ErrorManager.Error("Dữ liệu chưa hợp lệ để xuất HTML!");
        }
    }

